class SporadicTask:
    def __init__(self, e, d, p):
        self.e = e  # worst-case execution time
        self.d = d  # relative deadline
        self.p = p  # minimum inter-arrival separation (period)
        assert self.d <= self.p, "Task must have constrained deadline"

    def get_utilization(self):
        return self.e / self.p

def get_system_utilization(task_set):
    U_tau = 0.0
    for task in task_set:
        U_tau += task.get_utilization()
    return U_tau

import math

def dbf_task(task_i, t):
    if t <= 0:
        return 0
    num_jobs = math.floor((t - task_i.d) / task_i.p) + 1
    return max(0, num_jobs) * task_i.e

def dbf_system(task_set, t):
    total_demand = 0
    for task_i in task_set:
        total_demand += dbf_task(task_i, t)
    return total_demand

class EDPResource:
    def __init__(self, Pi, Theta, Delta):
        self.Pi = Pi      # Resource period
        self.Theta = Theta  # Resource capacity
        self.Delta = Delta  # Resource deadline
        assert self.Delta <= self.Pi, "Resource deadline must be <= period"

import math

def sbf_resource(resource_omega_i, t):
    Pi_i = resource_omega_i.Pi
    Theta_i = resource_omega_i.Theta
    Delta_i = resource_omega_i.Delta

    if t < Delta_i - Theta_i:
        return 0

    y = math.floor((t - (Delta_i - Theta_i)) / Pi_i)
    x = Pi_i + Delta_i - 2 * Theta_i

    return y * Theta_i + max(0, t - x - y * Pi_i)

